"""Save provisional static scan-transfer evidence without moving scientific data."""
from pathlib import Path
import csv,hashlib,json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
HERE=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def stats(e):
    e=np.asarray(e);r=np.linalg.norm(e,axis=1)
    return {'n':len(e),'rms_px':float(np.sqrt(np.mean(r*r))),'median_px':float(np.median(r)),'max_px':float(r.max()),'rms_column_px':float(np.sqrt(np.mean(e[:,0]**2))),'rms_line_px':float(np.sqrt(np.mean(e[:,1]**2)))}
def main():
    candidates=json.loads((HERE/'static_feature_candidates.json').read_text())['candidates'];sources=json.loads((HERE/'sources.json').read_text())['selected_band_reads']
    sourcehashes={s['selected_plane_sha256_little_endian_uint16_row_major'] for s in sources}
    for r in candidates:assert r['source_selected_plane_sha256'] in sourcehashes and r['target_selected_plane_sha256'] in sourcehashes
    result={'status':'static_image_supported_small_scan_coordinate_transfer','mapping':'003 column,line = 002 column,line + per-sensor translation','physical_sheet_mapping':'Unchanged from shared_plane_calibration.json; this transfer uses static panel/support/table features outside the removable targets.','fit_policy':'Six preselected start-panel/support raw-DN templates estimate a median translation. Independently designated start and long-range table features do not enter this fit. Weak/ambiguous features are rejected by fixed NCC, second-peak and gradient criteria, before reporting held-out errors. Two bands repeat the measurements; their errors are correlated and not independent extra physical controls.','visual_review':'Assistant review of source_start_pairs.png and static_feature_crops.png: admitted panel corners, support brackets, surviving table grid intersections and terminal marks show the same static material features. Rejected NIR ink features fade or overlap changed plant/shadow imagery. No plant tissue was matched to empty calibration geometry.','per_sensor':{},'limitations':['This is a locally initialized (±12 px) static-feature displacement check after direct visual alignment, not an unconstrained global matching test.','Subpixel maxima use parabolic interpolation of the raw template-correlation peak; decimal precision is not independent positional accuracy.','Small scan drift remains in held-out residuals. A single translation is an approximation, not proof of perfectly identical line motion.','Controls validate the visible static reference/table only and do not determine height-dependent camera rays.','D405 calibration-zero to plant reconstruction frame transfer is a separate problem.','Spatial wavelength dependence beyond these two sampled bands remains untested.','Q/Q0, panel reflectance and dark-reference uncertainty are unchanged.','No source arrays, reconstructed geometry, spectral assignments or previous results are modified.']}
    fig,axs=plt.subplots(2,2,figsize=(12,8),layout='constrained')
    for si,(camera,primary) in enumerate([('fx10',661),('fx17',1301)]):
        rows=[r for r in candidates if r['sensor']==camera and r['nominal_band_nm']==primary]
        accepted=[r for r in rows if r['passes_numeric_candidate_gate']];train=[r for r in accepted if r['split']=='start_fit'];assert len(train)==6
        t=np.median([r['shift_column_line'] for r in train],axis=0);tests={}
        for split in ['start_fit','start_holdout','long_holdout']:
            group=[r for r in accepted if r['split']==split];residual=np.array([r['shift_column_line'] for r in group])-t
            tests[split]={'features':[r['feature'] for r in group],'statistics':stats(residual),'residual_vectors_column_line':residual.tolist()}
        secondary={r['feature']:r for r in candidates if r['sensor']==camera and r['nominal_band_nm']==970 and r['passes_numeric_candidate_gate']}
        paired=[(r,secondary[r['feature']]) for r in accepted if r['feature'] in secondary]
        diffs=np.array([np.array(a['shift_column_line'])-b['shift_column_line'] for a,b in paired])
        result['per_sensor'][camera]={'primary_actual_wavelength_nm':train[0]['actual_wavelength_nm'],'translation_column_line_px':t.tolist(),'fit_and_holdouts':tests,'accepted_primary_features':accepted,'rejected_primary_features':[r for r in rows if not r['passes_numeric_candidate_gate']],'second_band_consistency':{'wavelength_nm':paired[0][1]['actual_wavelength_nm'],'matched_features':[a['feature'] for a,b in paired],'difference_statistics':stats(diffs),'correlated_measurements':True},'supported_native_source_extent_column_line':{'min':np.min([r['source_xy'] for r in accepted],axis=0).tolist(),'max':np.max([r['source_xy'] for r in accepted],axis=0).tolist()}}
        for group,marker,colour in [('start_fit','o','#236886'),('start_holdout','s','#8a6518'),('long_holdout','^','#a04c40')]:
            points=[r for r in accepted if r['split']==group];y=np.array([r['shift_column_line'] for r in points]);x=[r['source_xy'][1] for r in points]
            for dim in range(2):axs[si,dim].scatter(x,y[:,dim],marker=marker,label=group,color=colour,s=35)
        for dim in range(2):
            axs[si,dim].axhline(t[dim],color='#555',linestyle='--',label='start-fit median');axs[si,dim].set(xlabel='Calibration scan line',ylabel='003 − 002 displacement / px',title=f'{camera.upper()} '+['detector column','scan line'][dim]);axs[si,dim].grid(alpha=.2);axs[si,dim].legend(fontsize=8)
    fig.suptitle('Static background transfer: independent later controls reveal small residual scan drift');fig.savefig(HERE/'scan_transfer_residuals.png',dpi=150);plt.close(fig)
    result['source_hashes']={p.name:sha(p) for p in HERE.iterdir() if p.is_file() and p.name in ['sources.json','static_feature_candidates.json','probe_transfer.py','prepare_transfer.py','finalize_transfer.py','fx10_source_start_pairs.png','fx17_source_start_pairs.png','fx10_static_feature_crops.png','fx17_static_feature_crops.png']}
    (HERE/'scan_transfer.json').write_text(json.dumps(result,indent=2)+'\n')
    with (HERE/'static_controls.csv').open('w',newline='') as stream:
        fields=['sensor','band_nm','feature','split','source_column','source_line','target_column','target_line','delta_column','delta_line','NCC','accepted_numeric_and_visual']
        writer=csv.writer(stream);writer.writerow(fields)
        for r in candidates:writer.writerow([r['sensor'],r['actual_wavelength_nm'],r['feature'],r['split'],*r['source_xy'],*r['target_xy'],*r['shift_column_line'],r['NCC'],r['passes_numeric_candidate_gate']])
    intro='The same white panel, mounting brackets and exposed table markings are present in the empty-board scan 002 and plant scan 003. Their raw image signals support a small, measured scan-coordinate transfer for both hyperspectral cameras.'
    text='STATIC IMAGE TRANSFER, CALIBRATION 002 TO PLANTS 003\n\n'+intro+'\n\n'
    table=''
    for sensor,s in result['per_sensor'].items():
        t=s['translation_column_line_px'];start=s['fit_and_holdouts']['start_holdout']['statistics'];long=s['fit_and_holdouts']['long_holdout']['statistics'];second=s['second_band_consistency']['difference_statistics']
        text+=f'{sensor.upper()}: fit at {s["primary_actual_wavelength_nm"]:.2f} nm, six panel/support controls. Translation (column, line) = ({t[0]:.6f}, {t[1]:.6f}) pixels. Start hold-out n={start["n"]}, RMS={start["rms_px"]:.3f}px; long-range hold-out n={long["n"]}, RMS={long["rms_px"]:.3f}px, max={long["max_px"]:.3f}px. A second recorded band repeats {second["n"]} usable features; displacement differences RMS={second["rms_px"]:.3f}px. These repeats are correlated.\n\n'
        table+=f'<tr><td>{sensor.upper()}</td><td>{t[0]:+.4f}, {t[1]:+.4f}</td><td>{start["n"]} / {start["rms_px"]:.3f}</td><td>{long["n"]} / {long["rms_px"]:.3f} / {long["max_px"]:.3f}</td></tr>'
    text+='\n'.join(result['limitations'])+'\n\nEach observation, including rejected candidates, remains in static_feature_candidates.json and static_controls.csv. Crops show calibration on the left and plant scan on the right for each pair. Nominal anchor centres are template locations, not independently surveyed physical landmarks. Marker/panel detection errors and table-plane calibration errors must not be silently combined into a physical uncertainty estimate.\n'
    (HERE/'REPORT.txt').write_text(text,encoding='utf-8')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Measured calibration-to-plant scan transfer</title><style>body{font:16px/1.6 system-ui;background:#edf3f5;color:#162c38}main{max-width:1200px;margin:auto;padding:22px}section{background:white;padding:20px;border-radius:10px;margin:20px 0}img{max-width:100%;height:auto}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #cad6db;text-align:left}pre{white-space:pre-wrap;font:14px/1.6 system-ui}.crops{display:grid;grid-template-columns:1fr 1fr;gap:20px}a{color:#087188}@media(max-width:700px){.crops{display:block}}</style><main><p><a href="../index.html">Confirmed-board plane calibration</a></p><h1>Calibration scan → plant scan: measured static-image transfer</h1><section><p>'''+intro+'''</p><p>Six preselected start controls estimate translation. Separate table features later in the recording are held out. Repeated second-band measurements test consistency at two wavelengths and are not counted as independent physical controls.</p><table><thead><tr><th>Sensor</th><th>Δ column, line / px</th><th>Start held-out n / RMS</th><th>Later held-out n / RMS / max</th></tr></thead><tbody>'''+table+'''</tbody></table><p>These are native image coordinates; the result does not solve the height-dependent mapping from an elevated leaf to the HSI ray.</p></section><section><img src="scan_transfer_residuals.png" alt="Measured detector-column and scan-line displacement versus scan position"><p>A small residual drift remains. The constant translation is a supported approximation across the visible controls, not an assertion that the two scans are perfectly identical.</p></section><section><h2>Actual source images: 002 left, 003 right</h2><img src="fx10_source_start_pairs.png" alt="FX10 start reference panel and brackets, calibration versus plant run"><img src="fx17_source_start_pairs.png" alt="FX17 start reference panel and brackets, calibration versus plant run"></section><section><h2>Measured feature crops and exclusions</h2><p>Each pair is calibration left, plant right. Green candidates pass the fixed numerical gates and visual material-identity review; red candidates are rejected, commonly because ink becomes invisible or a plant changes the image.</p><div class="crops"><img src="fx10_static_feature_crops.png" alt="FX10 reviewed static image feature crops"><img src="fx17_static_feature_crops.png" alt="FX17 reviewed static image feature crops"></div></section><section><h2>Exact controls and scope</h2><p><a href="scan_transfer.json">Full transfer model and evidence</a> · <a href="static_controls.csv">All candidate controls</a> · <a href="sources.json">Recorded-plane fingerprints</a></p><pre>'''+text.replace('&','&amp;').replace('<','&lt;')+'''</pre></section></main></html>'''
    (HERE/'index.html').write_text(page,encoding='utf-8')
    (HERE/'checksums.json').write_text(json.dumps({p.name:sha(p) for p in HERE.iterdir() if p.is_file() and p.name!='checksums.json'},indent=2)+'\n')
    print(text)
if __name__=='__main__':main()
